def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    early_def = any(history[i][1] == 'D' for i in range(min(n, 20)))
    if early_def:
        if history[-1][1] == 'D':
            return 'D'
        return 'C'
    if n < 20:
        return 'C'
    ever_def = any(h[1] == 'D' for h in history)
    if ever_def:
        return 'C'
    else:
        return 'D'
